import "server-only";
import { serverEnv } from "@/lib/env";

/**
 * Optional raster illustration provider (OpenAI Images). Disabled unless
 * OPENAI_API_KEY is set AND image generation is enabled in admin settings.
 * Diagrams (Mermaid / structured visuals) are always generated by the main
 * AI provider; this only adds concept artwork.
 */
export function imageProviderConfigured() {
  return Boolean(serverEnv.openaiApiKey);
}

export async function generateConceptImage(prompt: string): Promise<Uint8Array> {
  if (!serverEnv.openaiApiKey) throw new Error("Image provider not configured");
  const res = await fetch("https://api.openai.com/v1/images/generations", {
    method: "POST",
    headers: { Authorization: `Bearer ${serverEnv.openaiApiKey}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      model: process.env.OPENAI_IMAGE_MODEL ?? "gpt-image-1",
      prompt: `Clean, minimal educational illustration, flat vector style, neutral background, no text artifacts. ${prompt}`,
      size: "1536x1024",
      n: 1,
    }),
  });
  if (!res.ok) throw new Error(`Image generation failed (${res.status})`);
  const json = (await res.json()) as { data?: Array<{ b64_json?: string }> };
  const b64 = json.data?.[0]?.b64_json;
  if (!b64) throw new Error("Image generation returned no image");
  return Uint8Array.from(Buffer.from(b64, "base64"));
}
